/// <summary>
/// Extension class for PurchLine table
/// </summary>
[ExtensionOf(tableStr(PurchLine))]
final class AVARUMPurchLineDbt_Extension
{

}

Method.Source:
/// <summary>
/// Returns the vendor name for the current purchase line
/// </summary>
/// <returns>Vendor name </returns>
[SysClientCacheDataMethodAttribute(true)]
public display VendName vendName_AVA()
{
    return VendTable::find(this.VendAccount).name();
}

/// <summary>
/// Return first loadId for this sales order line
/// </summary>
/// <returns>first loadId</returns>
[SysClientCacheDataMethodAttribute(true)]
display WHSLoadId displayFirstLoadId_AVA()
{
    WHSLoadLine  locWHSLoadLine;
    select firstonly LoadId, RecId, InventTransId from locWHSLoadLine
        where locWHSLoadLine.InventTransId==this.InventTransId
        && locWHSLoadLine.InventTransType==InventTransType::Purch;

    return locWHSLoadLine.LoadId;

}
